1	//! Rust port of `tests/test11.cpp`: run all eleven `idna` entry points over
2	//! every input and print the results on one space-separated line each.
3	//!
4	//! Inputs come from the command line; with no arguments the C++ driver falls
5	//! back to a fixed trio, and so does this one.
6	
7	#[path = "src/idna/mod.rs"]
8	mod idna;
9	
10	use std::env;
11	use std::ffi::OsString;
12	use std::io::{self, Write};
13	
14	fn main() {
15	    let mut inputs: Vec<Vec<u8>> = Vec::new();
16	
17	    // `argc > 1` in the original: every argument after the program name.
18	    for arg in env::args_os().skip(1) {
19	        inputs.push(arg_bytes(arg));
20	    }
21	
22	    if inputs.is_empty() {
23	        inputs = vec![
24	            b"one".to_vec(),
25	            b"two.three".to_vec(),
26	            b"four.five.six".to_vec(),
27	        ];
28	    }
29	
30	    let stdout = io::stdout();
31	    let mut out = io::BufWriter::new(stdout.lock());
32	
33	    // 调用11个不同的API
34	    for input in &inputs {
35	        let mut line: Vec<u8> = Vec::new();
36	        push_field(&mut line, &idna::to_ascii(input));
37	        push_field(&mut line, &idna::to_unicode(input));
38	        push_field(&mut line, &idna::punycode_encode(input));
39	        push_field(&mut line, &idna::punycode_decode(input));
40	        push_field(&mut line, bool_field(idna::is_valid_domain(input)));
41	        push_field(&mut line, bool_field(idna::is_valid_label(input)));
42	        push_field(&mut line, bool_field(idna::is_ascii_domain(input)));
43	        push_field(&mut line, bool_field(idna::is_idn_domain(input)));
44	        push_field(&mut line, &idna::to_lower(input));
45	        push_field(&mut line, &idna::normalize(input));
46	        line.extend_from_slice(idna::count_labels(input).to_string().as_bytes());
47	        line.push(b'\n');
48	
49	        if out.write_all(&line).is_err() {
50	            return;
51	        }
52	    }
53	
54	    let _ = out.flush();
55	}
56	
57	/// Appends one value plus the trailing space that `<< value << " "` emits.
58	fn push_field(line: &mut Vec<u8>, value: &[u8]) {
59	    line.extend_from_slice(value);
60	    line.push(b' ');
61	}
62	
63	/// `std::cout << bool` prints `1`/`0` unless `boolalpha` is set, and it isn't.
64	fn bool_field(value: bool) -> &'static [u8] {
65	    if value {
66	        b"1"
67	    } else {
68	        b"0"
69	    }
70	}
71	
72	/// Arguments reach `main` as raw bytes in C++, so take them as raw bytes here
73	/// too rather than requiring valid UTF-8.
74	#[cfg(unix)]
75	fn arg_bytes(arg: OsString) -> Vec<u8> {
76	    use std::os::unix::ffi::OsStringExt;
77	    arg.into_vec()
78	}
79	
80	#[cfg(not(unix))]
81	fn arg_bytes(arg: OsString) -> Vec<u8> {
82	    arg.to_string_lossy().into_owned().into_bytes()
83	}
