        open(STDERR, '>', '/dev/null');
        exec($bin, @$args) or exit(127);
    }
    binmode $fh;
    local $/; my $out = <$fh>; $out = '' unless defined $out;
    close($fh);
    my $rc = $? >> 8; my $sig = $? & 127;
    if ($env) { for my $k (keys %$env) { if (defined $saved{$k}) { $ENV{$k} = $saved{$k} } else { delete $ENV{$k} } } }
    return ($rc, $sig, $out);
}

# probe(\@args, $label, \%env) -> ($cpp_out, $field9_of_arg0)
sub probe {
    my ($args, $label, $env) = @_;
    $label = join(" | ", map { unpack("H*", $_) } @$args) unless defined $label;
    $COUNT++;
    my $envkey = $env ? join(",", map {"$_=$env->{$_}"} sort keys %$env) : "";
    $SEEN{$envkey . "\x01" . join("\x00", map { unpack("H*",$_) } @$args)} = 1;
    my ($rc1,$sg1,$o1) = run_bin($CPP, $args, $env);
    my ($rc2,$sg2,$o2) = run_bin($RS,  $args, $env);
    if ($rc1 != $rc2 || $sg1 != $sg2 || $o1 ne $o2) {
        my ($rc1b,$sg1b,$o1b) = run_bin($CPP, $args, $env);
        my ($rc2b,$sg2b,$o2b) = run_bin($RS,  $args, $env);
        my $stable = ($rc1b==$rc1 && $o1b eq $o1 && $rc2b==$rc2 && $o2b eq $o2) ? 1 : 0;
        push @DIFFS, [$label, $rc1, $o1, $rc2, $o2, $stable];
        printf STDERR "DIFF stable=%d label=%s\n  cpp rc=%d sig=%d out=%s\n  rs  rc=%d sig=%d out=%s\n",
            $stable, $label, $rc1, $sg1, unpack("H*",$o1), $rc2, $sg2, unpack("H*",$o2);
    }
    # to_ascii (field 1) == "xn--" . to_lower(input) and to_lower preserves
    # length, so field 9 is exactly bytes [4, 4+len(input)) of stdout.
    my $f9;
    if (@$args) {
        my $I = $args->[0];
        if (substr($o1,0,4) eq 'xn--' && length($o1) >= 4 + length($I)) {
            $f9 = substr($o1, 4, length($I));
        }
    }
    return ($o1, $f9);
}

sub report {
    printf("\nprobes=%d distinct=%d diffs=%d\n", $COUNT, scalar(keys %SEEN), scalar(@DIFFS));
}
1;

